import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { describe, expect, it } from 'vitest';

/**
 * RC-09 changed-path ownership-matrix counter-tests. The changed-path ownership
 * matrix (artifacts/agent-engineering-acceptance/runtime-authority-convergence-final/
 * changed-path-ownership.json) is generated by scripts/generate-rc09-ownership-matrix.mjs
 * from the EXACT cumulative candidate diff (accepted base -> RC-09 candidate) and
 * partitions it totally and disjointly:
 *
 *   - RC-owned paths map to EXACTLY ONE owner inside the required owner set,
 *     which is derived from the final spec's cumulativeOwnership.requiredSpecs;
 *   - excluded paths record the SHA, subject and workstream of the non-RC commit
 *     that first introduced them.
 *
 * The generator must be re-run whenever the accepted base or the RC-09 candidate
 * HEAD changes; the committed matrix is the deterministic evidence.
 */
const REPO_ROOT = process.cwd();
const MATRIX_RELATIVE = 'artifacts/agent-engineering-acceptance/runtime-authority-convergence-final/changed-path-ownership.json';
const MATRIX_PATH = join(REPO_ROOT, ...MATRIX_RELATIVE.split('/'));
const GENERATOR_RELATIVE = 'scripts/generate-rc09-ownership-matrix.mjs';
const FINAL_SPEC_RELATIVE = 'harness/specs/tasks/runtime-authority-convergence-final-acceptance.md';

interface MatrixEntry {
  path: string;
  rc: string | null;
  commit?: string | null;
  declaredBySpec?: boolean;
  excluded?: { commit: string; subject: string; workstream: string };
}

interface Matrix {
  schema: string;
  generatedAt?: string;
  baseSha: string;
  headSha: string;
  requiredOwners: string[];
  requiredSpecs: string[];
  totalPaths: number;
  rcOwnedPaths: number;
  excludedPaths: number;
  byRc: Record<string, number>;
  byExclusionWorkstream: Record<string, number>;
  entries: MatrixEntry[];
}

function git(args: string[]): string {
  return execFileSync('git', args, { cwd: REPO_ROOT, encoding: 'utf8', maxBuffer: 1024 * 1024 * 64 }).trim();
}

function readMatrix(): Matrix {
  return JSON.parse(readFileSync(MATRIX_PATH, 'utf8'));
}

/** Required owners as declared by the final spec, independent of the matrix. */
function declaredRequiredOwners(): string[] {
  const specPath = join(REPO_ROOT, ...FINAL_SPEC_RELATIVE.split('/'));
  const text = readFileSync(specPath, 'utf8').replace(/^\uFEFF/u, '').replaceAll('\r\n', '\n');
  const match = /^---\n([\s\S]*?)\n---(?:\n|$)/u.exec(text);
  expect(match).not.toBeNull();
  const names = [...match![1].matchAll(/-\s+(harness\/specs\/tasks\/rc[0-9a-z-]+\.md)/gu)].map((entry) => entry[1]);
  expect(names.length).toBeGreaterThan(0);
  const table: Record<string, string> = {
    RC00: 'RC-00', RC01: 'RC-01R', RC02: 'RC-02', RC03: 'RC-03', RC04: 'RC-04R',
    RC05: 'RC-05R', RC06A: 'RC-06A', RC06B: 'RC-06B', RC06C: 'RC-06C', RC06D: 'RC-06D',
    RC07: 'RC-07', RC08A: 'RC-08A', RC08B: 'RC-08B',
  };
  return [...new Set(names.map((name) => {
    const owner = /rc0(0|1|2|3|4|5|6[abcd]|7|8[ab])/iu.exec(name);
    expect(owner).not.toBeNull();
    return table[owner![0].toUpperCase()];
  }))].sort();
}

describe('RC-09 changed-path ownership matrix', () => {
  it('exists, uses the v2 schema, and matches the accepted base SHA', () => {
    expect(existsSync(MATRIX_PATH)).toBe(true);
    const matrix = readMatrix();
    expect(matrix.schema).toBe('runtime-authority-convergence-rc09-ownership/v2');
    expect(matrix.baseSha).toMatch(/^[a-f0-9]{40}$/);
    expect(matrix.headSha).toMatch(/^[a-f0-9]{40}$/);
  });

  it('derives the required owner set from the final spec, never from a directory scan', () => {
    const matrix = readMatrix();
    expect(matrix.requiredOwners).toEqual(declaredRequiredOwners());
    // RC-10 and the RC-01R variant specs are outside the accepted RC-00..RC-08B
    // set and may never own a changed path.
    expect(matrix.requiredOwners).not.toContain('RC-10');
    expect(matrix.requiredSpecs.some((spec) => spec.startsWith('rc10-'))).toBe(false);
    expect(matrix.requiredSpecs.some((spec) => spec.startsWith('rc01r-'))).toBe(false);
    expect(matrix.requiredSpecs.length).toBe(matrix.requiredOwners.length);
  });

  it('partitions the exact cumulative diff into RC-owned and excluded paths', () => {
    const matrix = readMatrix();
    // `-z` keeps non-ASCII paths raw, exactly like the generator and the validator.
    const actualDiff = git(['diff', '--name-only', '-z', `${matrix.baseSha}..${matrix.headSha}`])
      .split('\0')
      .filter(Boolean)
      .sort();
    const matrixPaths = matrix.entries.map((entry) => entry.path).sort();
    // The matrix is generated from the exact candidate diff — same set.
    expect(matrixPaths).toEqual(actualDiff);
    // Every path appears exactly once: the partition is total and disjoint.
    expect(new Set(matrixPaths).size).toBe(matrixPaths.length);
    expect(matrix.totalPaths).toBe(matrixPaths.length);

    const requiredOwners = new Set(matrix.requiredOwners);
    let rcOwned = 0;
    let excluded = 0;
    for (const entry of matrix.entries) {
      if (entry.rc !== null) {
        // An RC-owned path carries exactly one owner from the required set.
        expect(requiredOwners.has(entry.rc)).toBe(true);
        rcOwned += 1;
        continue;
      }
      // An excluded path names the non-RC commit that introduced it.
      expect(entry.excluded).toBeDefined();
      expect(entry.excluded!.commit).toMatch(/^[a-f0-9]{40}$/);
      expect(entry.excluded!.subject.trim()).not.toBe('');
      expect(entry.excluded!.workstream.trim()).not.toBe('');
      excluded += 1;
    }
    expect(rcOwned).toBe(matrix.rcOwnedPaths);
    expect(excluded).toBe(matrix.excludedPaths);
    expect(rcOwned + excluded).toBe(matrix.totalPaths);

    // The per-owner and per-workstream summaries are consistent with the entries.
    expect(Object.values(matrix.byRc).reduce((total, count) => total + count, 0)).toBe(rcOwned);
    expect(Object.values(matrix.byExclusionWorkstream).reduce((total, count) => total + count, 0)).toBe(excluded);
    for (const owner of Object.keys(matrix.byRc)) expect(requiredOwners.has(owner)).toBe(true);
  });

  it('the generator reproduces the committed matrix byte-for-byte', () => {
    const base = readMatrix().baseSha;
    const head = readMatrix().headSha;
    const regenerated = mkdtempSync(join(tmpdir(), 'rc09-matrix-'));
    const outputPath = join(regenerated, 'changed-path-ownership.json');
    try {
      execFileSync('node', [
        join(REPO_ROOT, GENERATOR_RELATIVE),
        '--base', base,
        '--head', head,
        '--output', outputPath,
      ], { cwd: REPO_ROOT, encoding: 'utf8', maxBuffer: 1024 * 1024 * 64 });

      // `generatedAt` is by construction the moment of generation, so it is the
      // only field allowed to differ. Everything else — path set, RC owners,
      // exclusions, owning commits, ordering — must reproduce exactly, otherwise
      // the committed matrix is not evidence of anything.
      const { generatedAt: _committedAt, ...committed } = readMatrix();
      const { generatedAt: _regeneratedAt, ...fresh } = JSON.parse(readFileSync(outputPath, 'utf8'));
      expect(fresh).toEqual(committed);
    } finally {
      rmSync(regenerated, { recursive: true, force: true });
    }
  }, 120_000);

  it('attributes every non-RC path to a commit that really introduced it', () => {
    const matrix = readMatrix();
    const excluded = matrix.entries.filter((entry) => entry.rc === null);
    // A sample is verified against git so the ledger cannot be hand-written.
    for (const entry of excluded.slice(0, 25)) {
      const firstTouch = git(['log', '--reverse', '--format=%H', '--name-only', `${matrix.baseSha}..${matrix.headSha}`, '--', entry.path])
        .split('\n')[0];
      expect(firstTouch).toBe(entry.excluded!.commit);
      expect(git(['show', '-s', '--format=%s', entry.excluded!.commit])).toBe(entry.excluded!.subject);
    }
  }, 120_000);
});
